// CloudtainerML rev0029 — Split-ranker contextualization toy.
// Inspired by ranker-once / contextualize-selected-splits architectures such as Avey. Symbolic C++ probe, not a paper reproduction.
#include <bits/stdc++.h>
using namespace std; static string q(const string&s){string o="\""; for(char c:s){ if(c=='"'||c=='\\') o+='\\'; o+=c;} return o+'"';}
struct Regime{string name; int chunks; double needle_strength,distractor_density,ranker_noise,locality,semantic_alias,chunk_cost;};
struct Method{string name; double ranker, local, recurrent, full, neighbor_expand, verify, cost_base; bool oracle=false;};
struct Row{string regime, method; int budget_chunks; double recall, exact_match,cost_frac,budget_over,distractor_leak,rank_miss,regret,score;};
int main(int argc,char**argv){string out=argc>1?argv[1]:"REV0029_RANKER_CONTEXTUALIZATION_SMOKE.json"; vector<Regime> regs={{"single_needle_sparse",128,0.95,0.25,0.10,0.08,0.12,1.0},{"buried_alias_decoys",192,0.76,0.82,0.22,0.06,0.88,1.0},{"local_story_continuity",96,0.55,0.38,0.14,0.82,0.20,1.0},{"multi_needle_distributed",256,0.70,0.56,0.20,0.20,0.42,1.0},{"noisy_ranker_small",64,0.62,0.45,0.62,0.18,0.36,1.0},{"long_redundant_haystack",512,0.82,0.32,0.18,0.12,0.22,1.0}};
 vector<Method> meth={{"dense_full_context",0,0,0,1,0,0,1.00,false},{"local_window_only",0,1,0,0,0,0,0.16,false},{"recurrent_summary",0,0,1,0,0,0,0.10,false},{"ranker_topk",1,0,0,0,0,0,0.18,false},{"ranker_plus_neighbors",1,0,0,0,0.45,0,0.25,false},{"ranker_verify_topk",1,0,0,0,0.20,0.65,0.33,false},{"cheap_semantic_router",0.58,0.20,0.08,0,0.20,0.20,0.20,false},{"oracle_split_ranker",1,0,0,0,0.5,1,0.22,true}};
 vector<int> budgets={2,4,8,16,32,64}; vector<Row> rows; map<string,int> wins, non;
 for(auto&r:regs) for(int B:budgets){vector<Row> cand; double frac=min(1.0,(double)B/r.chunks); for(auto&m:meth){ double rank_signal=max(0.0,r.needle_strength*(0.82*m.ranker+0.38*m.verify+0.12*m.neighbor_expand)-r.ranker_noise*(0.38+0.32*(1-m.verify))-r.semantic_alias*(0.28*(1-m.verify))); double local_signal=r.locality*(0.80*m.local+0.18*m.neighbor_expand); double recurrent_signal=m.recurrent*(0.30+0.30*(1-r.distractor_density)-0.25*r.semantic_alias); double full_signal=m.full*(0.93-0.10*r.distractor_density); double budget_support=1-exp(-B/(6.0+12.0*r.distractor_density+18.0*r.semantic_alias)); double recall=max(0.0,min(1.0,(rank_signal+local_signal+recurrent_signal+full_signal)*budget_support)); double leak=max(0.0,r.distractor_density*(0.45*m.full+0.34*m.recurrent+0.24*m.ranker*(1-m.verify)+0.18*m.neighbor_expand)+r.semantic_alias*(0.38*m.ranker*(1-m.verify))); double rank_miss=max(0.0,(1-recall)+0.22*r.ranker_noise*m.ranker+0.20*r.semantic_alias*m.ranker*(1-m.verify)); double cost=m.full?1.0:min(1.0,m.cost_base + frac*(0.82+0.28*m.neighbor_expand+0.18*m.verify)); if(m.oracle){recall=min(1.0,0.98*budget_support+0.18); leak=0.02*r.distractor_density; rank_miss=0.02; cost=min(0.62,0.10+frac*1.2);} double exact=recall*(1-0.55*leak)*(1-0.25*rank_miss); double budget_frac=min(1.0,(double)B/r.chunks*8.0+0.08); double over=max(0.0,cost-budget_frac); double score=(1-exact)+0.48*over+0.16*leak+0.22*rank_miss+0.05*cost; cand.push_back({r.name,m.name,B,recall,exact,cost,over,leak,rank_miss,0,score}); }
  double best=1e9; for(auto&x:cand)best=min(best,1-x.exact_match); for(auto&x:cand){x.regret=max(0.0,(1-x.exact_match)-best); x.score+=0.10*x.regret;} auto b=min_element(cand.begin(),cand.end(),[](auto&a,auto&b){return a.score<b.score;}); wins[b->method]++; auto bn=min_element(cand.begin(),cand.end(),[](auto&a,auto&b){if(a.method=="oracle_split_ranker")return false; if(b.method=="oracle_split_ranker")return true; return a.score<b.score;}); non[bn->method]++; rows.insert(rows.end(),cand.begin(),cand.end()); }
 ofstream f(out); f<<fixed<<setprecision(6); f<<"{\n  \"project\": \"CloudtainerML\",\n  \"revision\": \"rev0029\",\n  \"probe\": \"ranker_contextualization\",\n  \"summary\": {\n    \"row_count\": "<<rows.size()<<",\n    \"primary_metric\": {\"name\": \"score\", \"direction\": \"lower_is_better\", \"winner_field\": \"method\"},\n    \"winner_counts\": {"; bool first=true; for(auto&kv:wins){if(!first)f<<", "; first=false; f<<q(kv.first)<<": "<<kv.second;} f<<"},\n    \"nonoracle_winner_counts\": {"; first=true; for(auto&kv:non){if(!first)f<<", "; first=false; f<<q(kv.first)<<": "<<kv.second;} f<<"},\n    \"interpretation\": \"Ranker-once contextualization is attractive when recall can be protected by verification/neighbor expansion; semantic alias and noisy-ranker regimes expose candidate-set recall as the real bottleneck.\",\n    \"screen_regret_fields\": [\"exact_match\", \"cost_frac\", \"budget_over\", \"distractor_leak\", \"rank_miss\", \"regret\", \"score\"]\n  },\n  \"rows\": [\n"; for(size_t i=0;i<rows.size();++i){auto&r=rows[i]; f<<"    {\"regime\": "<<q(r.regime)<<", \"method\": "<<q(r.method)<<", \"budget_chunks\": "<<r.budget_chunks<<", \"recall\": "<<r.recall<<", \"exact_match\": "<<r.exact_match<<", \"cost_frac\": "<<r.cost_frac<<", \"budget_over\": "<<r.budget_over<<", \"distractor_leak\": "<<r.distractor_leak<<", \"rank_miss\": "<<r.rank_miss<<", \"regret\": "<<r.regret<<", \"score\": "<<r.score<<"}"<<(i+1==rows.size()?"\n":",\n"); } f<<"  ]\n}\n"; cerr<<"wrote "<<out<<" rows="<<rows.size()<<"\n"; }
